V C_TestCase::m_assertAlmostEqual(const Args& A) {
    V L_first = A.get(0, SY("first"), nullptr, "assertAlmostEqual");
    V L_second = A.get(1, SY("second"), nullptr, "assertAlmostEqual");
    V L_places = (A.size() > 2 || A.has_kw(SY("places"))) ? A.get(2, SY("places"), nullptr) : V(V::none());
    V L_msg = (A.size() > 3 || A.has_kw(SY("msg"))) ? A.get(3, SY("msg"), nullptr) : V(V::none());
    V L_delta = (A.size() > 4 || A.has_kw(SY("delta"))) ? A.get(4, SY("delta"), nullptr) : V(V::none());
    V L_diff;
    if ((L_first == L_second)) {
        return V::none();
    }
    L_diff = py::abs((L_first - L_second));
    if (!py_is(L_delta, V::none())) {
        if ((L_diff <= L_delta)) {
            return V::none();
        }
        py::raise(py::make_exc(SV("AssertionError"), Args{pm_pvzunit::f__fmt(Args{L_msg, py::percent(SV("%r != %r within %r delta (%r difference)"), V::tuple({L_first, L_second, L_delta, L_diff}))})}, ""));
    }
    if (py_is(L_places, V::none())) {
        L_places = V(7.0);
    }
    if ((py::round(L_diff, L_places) == V(0.0))) {
        return V::none();
    }
    py::raise(py::make_exc(SV("AssertionError"), Args{pm_pvzunit::f__fmt(Args{L_msg, py::percent(SV("%r != %r within %r places (%r difference)"), V::tuple({L_first, L_second, L_places, L_diff}))})}, ""));
    return V::none();
}

